#[test]
fn create_transfers_rejects_a_transfer_that_leaves_a_linked_chain_open() -> Result {
    let _guard = DB_LOCK.read().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let debit_account_id = tb::id();
        let credit_account_id = tb::id();
        client()
            .create_accounts(&[
                tb::Account {
                    id: debit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Account {
                    id: credit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
            ])
            .await?;
        let results = client()
            .create_transfers(&[tb::Transfer {
                id: tb::id(),
                debit_account_id: debit_account_id,
                credit_account_id: credit_account_id,
                amount: 100,
                ledger: 1,
                code: 1,
                flags: tb::TransferFlags::Linked,
                ..Default::default()
            }])
            .await?;
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, tb::CreateTransferStatus::LinkedEventChainOpen);
        let accounts = client().lookup_accounts(&[debit_account_id, credit_account_id]).await?;
        assert_eq!(accounts.len(), 2);
        assert_eq!(accounts[0].id, debit_account_id);
        assert_eq!(accounts[0].debits_posted, 0);
        assert_eq!(accounts[0].credits_posted, 0);
        assert_eq!(accounts[1].id, credit_account_id);
        assert_eq!(accounts[1].debits_posted, 0);
        assert_eq!(accounts[1].credits_posted, 0);
        Ok(())
    })
}

#[test]
