        assert_eq!(accounts.len(), 2);
        assert_eq!(accounts[0].id, debit_account_id);
        assert_eq!(accounts[0].debits_posted, 0);
        assert_eq!(accounts[0].credits_posted, 0);
        assert_eq!(accounts[1].id, credit_account_id);
