#[test]
fn query_accounts_pages_through_reversed_accounts_with_a_timestamp_cursor() -> Result {
    let _guard = DB_LOCK.read().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let account_1_id = tb::id();
        let account_2_id = tb::id();
        let account_3_id = tb::id();
        let user_data = tb::id();
        client()
            .create_accounts(&[
                tb::Account {
                    id: account_1_id,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Account {
                    id: account_2_id,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Account {
                    id: account_3_id,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
            ])
            .await?;
        let page_1 = client()
            .query_accounts(tb::QueryFilter {
                user_data_128: user_data,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert_eq!(page_1.len(), 2);
        assert_eq!(page_1[0].id, account_3_id);
        assert_eq!(page_1[1].id, account_2_id);
        let page_1_last = page_1[1];
        let cursor_1 = page_1_last.timestamp;
        let page_2 = client()
            .query_accounts(tb::QueryFilter {
                user_data_128: user_data,
                timestamp_max: cursor_1 - 1,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert_eq!(page_2.len(), 1);
        assert_eq!(page_2[0].id, account_1_id);
        let page_2_last = page_2[0];
        let cursor_2 = page_2_last.timestamp;
        let page_3 = client()
            .query_accounts(tb::QueryFilter {
                user_data_128: user_data,
                timestamp_max: cursor_2 - 1,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert!(page_3.is_empty());
        Ok(())
    })
}

