#[test]
fn query_transfers_pages_through_reversed_transfers_with_a_timestamp_cursor() -> Result {
    let _guard = DB_LOCK.read().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let debit_account_id = tb::id();
        let credit_account_id = tb::id();
        let transfer_1_id = tb::id();
        let transfer_2_id = tb::id();
        let transfer_3_id = tb::id();
        let user_data = tb::id();
        client()
            .create_accounts(&[
                tb::Account {
                    id: debit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Account {
                    id: credit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
            ])
            .await?;
        client()
            .create_transfers(&[
                tb::Transfer {
                    id: transfer_1_id,
                    debit_account_id: debit_account_id,
                    credit_account_id: credit_account_id,
                    amount: 10,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Transfer {
                    id: transfer_2_id,
                    debit_account_id: debit_account_id,
                    credit_account_id: credit_account_id,
                    amount: 20,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Transfer {
                    id: transfer_3_id,
                    debit_account_id: debit_account_id,
                    credit_account_id: credit_account_id,
                    amount: 30,
                    user_data_128: user_data,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
            ])
            .await?;
        let page_1 = client()
            .query_transfers(tb::QueryFilter {
                user_data_128: user_data,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert_eq!(page_1.len(), 2);
        assert_eq!(page_1[0].id, transfer_3_id);
        assert_eq!(page_1[0].amount, 30);
        assert_eq!(page_1[1].id, transfer_2_id);
        assert_eq!(page_1[1].amount, 20);
        let page_1_last = page_1[1];
        let cursor_1 = page_1_last.timestamp;
        let page_2 = client()
            .query_transfers(tb::QueryFilter {
                user_data_128: user_data,
                timestamp_max: cursor_1 - 1,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert_eq!(page_2.len(), 1);
        assert_eq!(page_2[0].id, transfer_1_id);
        assert_eq!(page_2[0].amount, 10);
        let page_2_last = page_2[0];
        let cursor_2 = page_2_last.timestamp;
        let page_3 = client()
            .query_transfers(tb::QueryFilter {
                user_data_128: user_data,
                timestamp_max: cursor_2 - 1,
                limit: 2,
                flags: tb::QueryFilterFlags::Reversed,
                ..Default::default()
            })
            .await?;
        assert!(page_3.is_empty());
        Ok(())
    })
}

