// Suite: closing_transfer

#[test]
fn closing_transfer_closes_both_accounts_with_a_pending_closing_transfer() -> Result {
    let _guard = DB_LOCK.read().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let account_1_id = tb::id();
        let account_2_id = tb::id();
        client()
            .create_accounts(&[
                tb::Account {
                    id: account_1_id,
                    ledger: 1,
                    code: 1,
                    flags: tb::AccountFlags::History,
                    ..Default::default()
                },
                tb::Account {
                    id: account_2_id,
                    ledger: 1,
                    code: 1,
                    flags: tb::AccountFlags::History,
                    ..Default::default()
                },
            ])
            .await?;
        let results = client()
            .create_transfers(&[tb::Transfer {
                id: tb::id(),
                debit_account_id: account_1_id,
                credit_account_id: account_2_id,
                amount: 0,
                ledger: 1,
                code: 1,
                flags: tb::TransferFlags::Pending
                    | tb::TransferFlags::ClosingDebit
                    | tb::TransferFlags::ClosingCredit,
                ..Default::default()
            }])
            .await?;
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, tb::CreateTransferStatus::Created);
        let accounts = client().lookup_accounts(&[account_1_id, account_2_id]).await?;
        assert_eq!(accounts.len(), 2);
        assert_eq!(accounts[0].id, account_1_id);
        assert_eq!(accounts[0].flags, tb::AccountFlags::History | tb::AccountFlags::Closed);
        assert_eq!(accounts[1].id, account_2_id);
        assert_eq!(accounts[1].flags, tb::AccountFlags::History | tb::AccountFlags::Closed);
        Ok(())
    })
}

