// Suite: import_accounts

#[test]
fn import_accounts_imports_accounts_with_explicit_timestamps() -> Result {
    let _guard = DB_LOCK.write().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let reference_results = client()
            .create_accounts(&[tb::Account {
                id: tb::id(),
                ledger: 1,
                code: 1,
                ..Default::default()
            }])
            .await?;
        let reference_result = reference_results[0];
        let reference = reference_result.timestamp;
        std::thread::sleep(Duration::from_millis(10));
        let account_1_id = tb::id();
        let account_2_id = tb::id();
        let results = client()
            .create_accounts(&[
                tb::Account {
                    id: account_1_id,
                    ledger: 1,
                    code: 1,
                    flags: tb::AccountFlags::Imported,
                    timestamp: reference + 1,
                    ..Default::default()
                },
                tb::Account {
                    id: account_2_id,
                    ledger: 1,
                    code: 1,
                    flags: tb::AccountFlags::Imported,
                    timestamp: reference + 2,
                    ..Default::default()
                },
            ])
            .await?;
        assert_eq!(results.len(), 2);
        assert_eq!(results[0].status, tb::CreateAccountStatus::Created);
        assert_eq!(results[1].status, tb::CreateAccountStatus::Created);
        let accounts = client().lookup_accounts(&[account_1_id, account_2_id]).await?;
        assert_eq!(accounts.len(), 2);
        assert_eq!(accounts[0].id, account_1_id);
        assert_eq!(accounts[0].flags, tb::AccountFlags::Imported);
        assert_eq!(accounts[1].id, account_2_id);
        assert_eq!(accounts[1].flags, tb::AccountFlags::Imported);
        let result_1 = results[0];
        let result_2 = results[1];
        let account_1 = accounts[0];
        let account_2 = accounts[1];
        assert_eq!(result_1.timestamp, reference + 1);
        assert_eq!(result_2.timestamp, reference + 2);
        assert_eq!(account_1.timestamp, result_1.timestamp);
        assert_eq!(account_2.timestamp, result_2.timestamp);
        Ok(())
    })
}

