// Suite: create_transfers_concurrent

#[test]
fn create_transfers_concurrent_applies_transfers_submitted_concurrently() -> Result {
    let _guard = DB_LOCK.read().unwrap_or_else(PoisonError::into_inner);
    block_on(async {
        let debit_account_id = tb::id();
        let credit_account_id = tb::id();
        client()
            .create_accounts(&[
                tb::Account {
                    id: debit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
                tb::Account {
                    id: credit_account_id,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                },
            ])
            .await?;
        std::thread::scope(|scope| {
            for _ in 0..100 {
                scope.spawn(|| block_on(client().create_transfers(&[tb::Transfer {
                    id: tb::id(),
                    debit_account_id: debit_account_id,
                    credit_account_id: credit_account_id,
                    amount: 10,
                    ledger: 1,
                    code: 1,
                    ..Default::default()
                }])).expect("concurrent call failed"));
            }
        });
        let accounts = client().lookup_accounts(&[debit_account_id, credit_account_id]).await?;
        assert_eq!(accounts.len(), 2);
        assert_eq!(accounts[0].id, debit_account_id);
        assert_eq!(accounts[0].debits_posted, 1000);
        assert_eq!(accounts[0].credits_posted, 0);
        assert_eq!(accounts[1].id, credit_account_id);
        assert_eq!(accounts[1].debits_posted, 0);
        assert_eq!(accounts[1].credits_posted, 1000);
        Ok(())
    })
}

